// Vapi'ye dönecek araç yanıtı: { results: [{ toolCallId, result }] }
const plan = $('Araç Planı').first().json;

let yanit = null;
try {
  yanit = $('Bitrix: Araç Kaydı').first().json; // kayıt yoksa bu node çalışmamıştır
} catch (e) {
